height:min(90dvh,850px);border:0;border-radius:20px;box-shadow:0 24px 80px #111a1f40}.lp-dialog::backdrop{background:#121b19a8}.lp-dialog-head{display:flex;justify-content:space-between;gap:14px;padding:24px 26px 18px;border-bottom:1px solid #e0e7e4}.lp-dialog-head h2{margin:4px 0;font:600 26px var(--font-verly-display)}.lp-dialog-head p:last-child{margin:0;color:#53615c;font-size:15px}.lp-close{display:grid;place-items:center;flex:0 0 44px;width:44px;height:44px;border:0;border-radius:50%;background:#eff3f1;color:#141a1f;cursor:pointer}.lp-dialog-body{display:grid;gap:20px;padding:22px 26px;max-height:60vh;overflow:auto}.lp-info-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.lp-info-grid div{display:grid;gap:5px;padding:13px;border-radius:10px;background:#f3f5f4}.lp-info-grid small{color:#596761;font-size:15px}.lp-info-grid strong{font-size:16px}.lp-note{margin:0;padding:15px;border-left:3px solid #2e7d7a;border-radius:0 10px 10px 0;background:#eff7f5}.lp-note p{margin:4px 0 0;line-height:1.5}.lp-drawing{max-width:260px;margin:auto}.lp-measure-pending{display:flex;align-items:center;gap:12px;padding:15px;border:1px solid #ecc58f;border-radius:12px;background:#fbe8cf;color:#753c08}.lp-measure-pending svg{flex:0 0 24px}.lp-measure-pending div{display:grid;gap:3px}.lp-measure-pending span,.lp-form-copy{font-size:15px;line-height:1.45}.lp-dialog-actions{display:flex;align-items:center;flex-wrap:wrap;gap:9px;padding:14px 26px 22px;border-top:1px solid #e0e7e4}.lp-dialog-actions .preview-button{display:inline-flex;align-items:center;gap:7px}.lp-text-action{min-height:44px;margin-left:auto;border:0;background:transparent;color:#81440d;font:600 15px var(--font-verly-body);text-decoration:underline;text-underline-offset:3px;cursor:pointer}.lp-form-copy{margin:0;color:#495651}.lp-form-actions{display:flex;justify-content:space-between;gap:12px;padding-top:4px}.preview-form-field{display:grid;gap:7px;color:#26322e;font-size:16px}.preview-form-field input,.preview-form-field select,.preview-form-field textarea{min-height:48px;padding:10px 12px;border:1px solid #bcc9c4;border-radius:9px;background:#fff;color:#141a1f;font:400 16px var(--font-verly-body)}.preview-form-field textarea{min-height:88px}.preview-notice{position:fixed;z-index:20;right:20px;bottom:20px;padding:14px 18px;border-radius:12px;background:#141a1f;color:#fff;box-shadow:0 8px 30px #1114}.preview-notice span{color:#cad6d2}.lp-undo{min-height:44px;margin:0 7px;padding:5px 9px;border:1px solid #9fb8ae;border-radius:7px;background:#263b35;color:white;font:600 15px var(--font-verly-body);cursor:pointer}.preview-empty{display:grid;justify-items:center;gap:5px;padding:48px 12px;color:#53615f}.preview-empty strong{color:#141a1f}
@media(max-width:720px){.lp-head,.lp-queue-head{align-items:flex-start;flex-direction:column}.lp-live{align-self:flex-start}.lp-summary{gap:7px}.lp-summary article{padding:12px 10px}.lp-summary span{font-size:15px}.lp-summary strong{font-size:19px}.lp-workspace{padding:16px}.lp-search{width:100%;min-width:0}.lp-row{grid-template-columns:38px minmax(0,1fr) 15px;gap:9px;padding:13px 0}.lp-avatar{width:36px;height:36px}.lp-row-meta{grid-column:2;grid-row:2;justify-items:start;display:flex;align-items:center;flex-wrap:wrap}.lp-row-meta b{margin-left:auto}.lp-main{grid-column:2;grid-row:1}.lp-arrow{grid-column:3;grid-row:1}.lp-last{white-space:normal;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical}.lp-dialog-head,.lp-dialog-body{padding-left:18px;padding-right:18px}.lp-dialog-actions{padding-left:18px;padding-right:18px}.lp-info-grid{gap:8px}.lp-dialog-actions>*{flex:1 1 42%}.lp-text-action{margin-left:0}.lp-form-actions{flex-wrap:wrap}.lp-form-actions>*{flex:1}}
.lp-search{display:flex;align-items:center;gap:10px}.lp-undo{min-height:44px}@media(max-width:720px){.preview-notice{right:12px;bottom:calc(90px + env(safe-area-inset-bottom));left:12px}.lp-undo{min-height:44px}}
